#!/usr/bin/env python3
"""
American Express (AXP) Historical Stock Performance Report Generator
1972-2026 Comprehensive Analysis
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from matplotlib.ticker import FuncFormatter
import base64
from io import BytesIO
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# Load and prepare data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'].str[:10])
df = df.sort_values('Date').reset_index(drop=True)

print(f"Data loaded: {len(df)} rows from {df['Date'].min()} to {df['Date'].max()}")

# Calculate daily returns
df['Daily_Return'] = df['Close'].pct_change()

# ============ KPI CALCULATIONS ============
print("Calculating KPIs...")

# First and last prices
first_price = df['Close'].iloc[0]
last_price = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]

# Cumulative Return
cumulative_return = ((last_price / first_price) - 1) * 100

# CAGR
years = (last_date - first_date).days / 365.25
cagr = (((last_price / first_price) ** (1/years)) - 1) * 100

# Annualized Volatility (using daily std * sqrt(252))
daily_vol = df['Daily_Return'].std()
annualized_vol = daily_vol * np.sqrt(252) * 100

# Maximum Drawdown
df['Cumulative_Max'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cumulative_Max']) / df['Cumulative_Max']
max_drawdown = df['Drawdown'].min() * 100
max_drawdown_date = df.loc[df['Drawdown'].idxmin(), 'Date']

# Total Dividends
total_dividends = df['Dividends'].sum()

# Find all-time high and low
ath_price = df['Close'].max()
ath_date = df.loc[df['Close'].idxmax(), 'Date']
atl_price = df['Close'].min()
atl_date = df.loc[df['Close'].idxmin(), 'Date']

# ============ BULL/BEAR PHASE ANALYSIS ============
print("Analyzing bull/bear phases...")

# Identify peaks and troughs
df['Is_Peak'] = (df['Close'].shift(1) < df['Close']) & (df['Close'] > df['Close'].shift(-1))
df['Is_Trough'] = (df['Close'].shift(1) > df['Close']) & (df['Close'] < df['Close'].shift(-1))

peaks = df[df['Is_Peak'] == True].copy()
troughs = df[df['Is_Trough'] == True].copy()

# Major market events to identify
events = {
    '1973-74 Oil Crisis': ('1973-01-01', '1974-12-31'),
    '1987 Black Monday': ('1987-01-01', '1987-12-31'),
    '2000 Dot-com Bubble': ('2000-03-01', '2002-10-01'),
    '2008 Financial Crisis': ('2007-10-01', '2009-03-01'),
    'COVID-19 Crash': ('2020-02-01', '2020-03-31'),
}

# Calculate drawdowns for major events
event_drawdowns = {}
for event_name, (start, end) in events.items():
    mask = (df['Date'] >= start) & (df['Date'] <= end)
    if mask.sum() > 0:
        event_data = df[mask]
        peak = event_data['Close'].max()
        trough = event_data['Close'].min()
        drawdown = ((trough - peak) / peak) * 100
        event_drawdowns[event_name] = {
            'peak': peak,
            'trough': trough,
            'drawdown': drawdown
        }

# ============ DECADE ANALYSIS ============
print("Analyzing decades...")

def get_decade_stats(start_year, end_year):
    mask = (df['Date'].dt.year >= start_year) & (df['Date'].dt.year <= end_year)
    decade_df = df[mask]
    if len(decade_df) < 2:
        return None
    start_price = decade_df['Close'].iloc[0]
    end_price = decade_df['Close'].iloc[-1]
    years = (decade_df['Date'].iloc[-1] - decade_df['Date'].iloc[0]).days / 365.25
    ret = ((end_price / start_price) - 1) * 100
    cagr_decade = (((end_price / start_price) ** (1/years)) - 1) * 100 if years > 0 else 0
    vol = decade_df['Daily_Return'].std() * np.sqrt(252) * 100
    dividends = decade_df['Dividends'].sum()
    return {
        'start_price': start_price,
        'end_price': end_price,
        'return': ret,
        'cagr': cagr_decade,
        'volatility': vol,
        'dividends': dividends,
        'start_date': decade_df['Date'].iloc[0],
        'end_date': decade_df['Date'].iloc[-1]
    }

decades = {
